  "T3 Code on {0} stops, rebuilds its database, and starts again. It will be offline for about {1} min. Running agents stop when it restarts.":
    "{0} 上的 T3 Code 会停止、重建数据库，然后重新启动。期间会离线约 {1} 分钟。重启时，正在运行的智能体会停止。",
  "T3 Code removed {0} hidden character {1}. Read the prompt before you send it.":
    "T3 Code 移除了 {0} 个隐藏字符{1}。发送前请先阅读 提示词。",
  "T3 Code Web": "T3 Code 网页版",
  "T3 Code will download and install version{0} {1} locally.":
    "T3 Code 将在本地下载并安装版本{0}{1}。",
  "T3 Code will restart and bring the Windows backend back up alongside WSL.":
    "T3 Code 将重启，并在 WSL 之外重新启动 Windows 后端。",
  "T3 Code will restart and start only the WSL backend. Your Windows-side projects won't be accessible until you turn this off again.":
    "T3 Code 将重启，并且只启动 WSL 后端。在再次关闭此选项之前，Windows 端的项目将无法访问。",
  "T3 Code will restart and start running a server on this computer again.":
    "T3 Code 将重启，并重新在此计算机上运行服务器。",
  "T3 Code will restart on the Windows backend. Threads and projects opened against WSL stay safe inside the distro and become available again when you re-enable WSL.":
    "T3 Code 将在 Windows 后端上重启。针对 WSL 打开的线程和项目会安全保留在发行版中，重新启用 WSL 后将再次可用。",
  "T3 Code will restart the local backend with Tailscale Serve enabled and ask Tailscale to proxy HTTPS traffic to this backend.":
    "T3 Code 将启用 Tailscale Serve 并重启本地后端，同时请求 Tailscale 将 HTTPS 流量代理到此后端。",
  "T3 Code will restart the local backend without Tailscale Serve.":
    "T3 Code 将在不启用 Tailscale Serve 的情况下重启本地后端。",
  "T3 Code will restart the WSL backend on the new distro. Sessions still running on the current distro will be interrupted.":
    "T3 Code 将在新的发行版上重启 WSL 后端。仍在当前发行版上运行的会话将被中断。",
  "T3 Code will restart without running a server on this computer. Any agents and terminals running here will stop, and other devices will no longer be able to connect to this computer. Your projects, history, and remote environments are unaffected.":
    "T3 Code 将重启，且不会在此计算机上运行服务器。此处运行的所有智能体和终端都将停止，其他设备也将无法再连接到此计算机。你的项目、历史记录和远程环境不受影响。",
  "T3 Code's capture helper lets you capture other apps and return to your draft. It's included with T3 Code.":
    "T3 Code 的捕获助手可让你捕获其他应用并返回草稿。它已随 T3 Code 一同提供。",
  "t3 command": "t3 命令",
  "T3 Connect": "T3 Connect",
  "T3 Connect access was revoked and a host space is now available.":
    "T3 Connect 访问权限已被撤销，现已空出一个主机名额。",
  "T3 Connect access will be revoked, any managed tunnel will be removed, and a host space will become available. Local connections on your devices are not changed.":
    "T3 Connect 访问权限将被撤销，所有托管隧道都将被移除，并会空出一个主机名额。你设备上的本地连接不会改变。",
  "T3 Connect enabled": "T3 Connect 已启用",
  "T3 Connect is not available in this build.": "此版本中无法使用 T3 Connect。",
  "T3 Connect is on for this computer. Sign in to the app with the same account.":
    "此计算机已开启 T3 Connect。请使用同一账号登录应用。",
  "T3 Connect is on, but other devices cannot reach this environment.":
    "T3 Connect 已开启，但其他设备无法访问此环境。",
  "T3 Connect is on, but the app cannot reach this computer.":
    "T3 Connect 已开启，但应用无法访问这台计算机。",
  "T3 Connect is on. Reachability has not been checked yet.": "T3 Connect 已开启。尚未检查可达性。",
  "T3 Connect is out of sync. This environment is linked only to publish agent activity, so other devices cannot connect. Turn T3 Connect on to repair it.":
    "T3 Connect 状态不同步。此环境仅关联用于发布智能体活动，因此其他设备无法连接。请开启 T3 Connect 进行修复。",
  "T3 Connect is unavailable. Try again.": "T3 Connect 不可用，请重试。",
  "T3 Connect keeps webhook requests for up to 24 hours while this environment is offline.":
    "此环境离线期间，T3 Connect 最多会保留 Webhook 请求 24 小时。",
