  "The clone failed.": "克隆失败。",
  "The clone started, but its project did not appear.": "克隆已开始，但项目未出现。",
  "The cloud provider can detect your language automatically.": "云端服务商可以自动检测你的语言。",
  "The code expired.": "代码已过期。",
  "The color scheme pages are told to prefer. System follows your OS setting.":
    "告知页面优先使用的配色方案。选择“系统”则跟随操作系统设置。",
  "The composer is busy; try again once it is ready.": "输入框正忙，请稍后再试。",
