  "The diagram renderer failed to load.": "图表渲染器加载失败。",
  "The diff could not be loaded, so excerpts are missing: {0}":
    "无法加载差异，因此缺少部分摘录：{0}",
  "The environment is not connected.": "环境未连接。",
  "The environment is saved and will reconnect on app startup.":
    "环境已保存，将在应用启动时重新连接。",
  "The environment request failed.": "环境请求失败。",
  "The environment's server leases devices from your Simlock gateway and releases them when they close.":
    "该环境的服务器会从你的 Simlock 网关租用设备，并在设备关闭时释放。",
  "The environment's server signs in to Expo and starts the sessions. Without a token here it uses EXPO_TOKEN, then its eas login.":
    "该环境的服务器会登录 Expo 并启动会话。此处未设置 Token 时，会使用 EXPO_TOKEN，然后使用其 eas 登录。",
  "The extension isn't ready yet. Try again in a moment.": "扩展尚未就绪，请稍后再试。",
  "The file could not be loaded. It may have been moved or deleted.":
    "无法加载该文件。它可能已被移动或删除。",
  "The file is binary and cannot be displayed as text.": "该文件是二进制文件，无法以文本显示。",
  "The font is damaged or unsupported.": "字体已损坏或不受支持。",
  "The guest sees the thread as you do, including command output and the agent's reasoning. Each message they send waits for you.":
    "访客看到的内容与你相同，包括命令输出和智能体的推理过程。他们发送的每条消息都会等待你确认。",
  "The host withheld part of this diff: a binary file, or a change too large to inline.":
    "主机未提供此差异的一部分内容：二进制文件，或改动过大而无法内联展示。",
  "The hosts were searched for it. Try fewer words, or search by number, author or branch.":
    "已在各主机上搜索过。请尝试更少的词，或按编号、作者或分支搜索。",
  "The hub's management key is deleted from this server. Its accounts leave the Limits view; the hub itself is untouched. Add it again with the URL and key to bring them back.":
    "该 Hub 的管理密钥已从此服务器删除。其账户会从“限额”视图中移出；Hub 本身不受影响。用 URL 和密钥重新添加即可恢复。",
  "The integrated browser is unavailable in this runtime.": "当前运行时无法使用内置浏览器。",
  "The keybinding was not removed.": "快捷键未移除。",
  "The keybinding was not saved.": "快捷键未保存。",
  "The keybindings file was not opened.": "快捷键配置文件未打开。",
  "The license manifest could not load.": "无法加载许可证清单。",
  "The license manifest took too long to load.": "许可证清单加载超时。",
  "The line is where even spending would be.": "这条线表示均匀消费应在的位置。",
  "The link is missing its authorization request. Re-run `t3 connect` in your terminal and open the freshly printed URL.":
    "该链接缺少授权请求。请在终端中重新运行 `t3 connect`，然后打开最新打印的 URL。",
  "The link works once and expires in 24 hours.": "该链接仅可使用一次，并在 24 小时后过期。",
  "The main thread gets this side chat with your next message there.":
    "你在主线程发送下一条消息时，这段侧聊会一并带上。",
  "The managed tunnel was removed. Agent activity publishing stays on.":
    "托管隧道已移除。智能体活动发布保持开启。",
  "The media action failed.": "媒体操作失败。",
  "The model list couldn't load.": "无法加载模型列表。",
